contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(address other, uint256 v) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (v)); require(v <= 1000000000000000000000000000000);
        require(other != address(0));
        require(other != address(this));
        require(address(this).balance >= v);

        uint256 beforeMine = c.balances(address(this)); if (__ESBMC_reverted()) return;
        uint256 beforeOther = c.balances(other); if (__ESBMC_reverted()) return;

        c.Deposit{value: v}(); if (__ESBMC_reverted()) return;

        uint256 afterMine = c.balances(address(this)); if (__ESBMC_reverted()) return;
        uint256 afterOther = c.balances(other); if (__ESBMC_reverted()) return;

        assert(afterMine == beforeMine + v && afterOther == beforeOther);
    }

    receive() external payable {}
}

